1003	    protected Mono<View> loadView(final String viewName, final Locale locale) {
1004	
1005	        final AutowireCapableBeanFactory beanFactory = getApplicationContext().getAutowireCapableBeanFactory();
1006	
1007	        final boolean viewBeanExists = beanFactory.containsBean(viewName);
1008	        final Class<?> viewBeanType = viewBeanExists? beanFactory.getType(viewName) : null;
1009	
1010	        final ThymeleafReactiveView view;
1011	        if (viewBeanExists && viewBeanType != null && ThymeleafReactiveView.class.isAssignableFrom(viewBeanType)) {
1012	            // AppCtx has a bean with name == viewName, and it is a View bean. So let's use it as a prototype!
1013	            //
1014	            // This can mean two things: if the bean has been defined with scope "prototype", we will just use it.
1015	            // If it hasn't we will create a new instance of the view class and use its properties in order to
1016	            // configure this view instance (so that we don't end up using the same bean from several request threads).
1017	            //
1018	            // Note that, if Java-based configuration is used, using @Scope("prototype") would be the only viable
1019	            // possibility here.
1020	
1021	            final BeanDefinition viewBeanDefinition =
1022	                    (beanFactory instanceof ConfigurableListableBeanFactory ?
1023	                            ((ConfigurableListableBeanFactory)beanFactory).getBeanDefinition(viewName) :
1024	                            null);
1025	
1026	            if (viewBeanDefinition == null || !viewBeanDefinition.isPrototype()) {
1027	                // No scope="prototype", so we will just apply its properties. This should only happen with XML config.
1028	                final ThymeleafReactiveView viewInstance = BeanUtils.instantiateClass(getViewClass());
1029	                view = (ThymeleafReactiveView) beanFactory.configureBean(viewInstance, viewName);
1030	            } else {
1031	                // This is a prototype bean. Use it as such.
1032	                view = (ThymeleafReactiveView) beanFactory.getBean(viewName);
1033	            }
1034	
1035	        } else {
1036	
1037	            final ThymeleafReactiveView viewInstance = BeanUtils.instantiateClass(getViewClass());
1038	
1039	            if (viewBeanExists && viewBeanType == null) {
1040	                // AppCtx has a bean with name == viewName, but it is an abstract bean. We still can use it as a prototype.
1041	
1042	                // The AUTOWIRE_NO mode applies autowiring only through annotations
1043	                beanFactory.autowireBeanProperties(viewInstance, AutowireCapableBeanFactory.AUTOWIRE_NO, false);
1044	                // A bean with this name exists, so we apply its properties
1045	                beanFactory.applyBeanPropertyValues(viewInstance, viewName);
1046	                // Finally, we let Spring do the remaining initializations (incl. proxifying if needed)
1047	                view = (ThymeleafReactiveView) beanFactory.initializeBean(viewInstance, viewName);
1048	
1049	            } else {
1050	                // Either AppCtx has no bean with name == viewName, or it is of an incompatible class. No prototyping done.
1051	
1052	                // The AUTOWIRE_NO mode applies autowiring only through annotations
1053	                beanFactory.autowireBeanProperties(viewInstance, AutowireCapableBeanFactory.AUTOWIRE_NO, false);
1054	                // Finally, we let Spring do the remaining initializations (incl. proxifying if needed)
1055	                view = (ThymeleafReactiveView) beanFactory.initializeBean(viewInstance, viewName);
1056	
1057	            }
1058	
1059	        }
1060	
1061	        view.setTemplateEngine(getTemplateEngine());
1062	        view.setStaticVariables(getStaticVariables());
1063	
1064	        // We give view beans the opportunity to specify the template name to be used
1065	        if (view.getTemplateName() == null) {
1066	            view.setTemplateName(viewName);
1067	        }
1068	
1069	        // We set the media types from the view resolver only if no value has already been set at the view def.
1070	        if (!view.isSupportedMediaTypesSet()) {
1071	            view.setSupportedMediaTypes(getSupportedMediaTypes());
1072	        }
1073	
1074	        // We set the default charset from the view resolver only if no value has already been set at the view def.
1075	        if (!view.isDefaultCharsetSet()) {
1076	            view.setDefaultCharset(getDefaultCharset());
1077	        }
1078	
1079	        // We set the locale from the view resolver only if no value has already been set at the view def.
1080	        if (locale != null && view.getLocale() == null) {
1081	            view.setLocale(locale);
1082	        }
1083	
1084	        /*
1085	         * Set the reactive operation-related flags
1086	         */
1087	
1088	        // We determine if there is actually a reason for using chunked execution for this specific view name,
1089	        // based on the ViewResolver configuration
1090	        final boolean shouldUseChunkedExecution = shouldUseChunkedExecution(viewName);
1091	
1092	        if (shouldUseChunkedExecution && view.getNullableResponseMaxChunkSize() == null) {
1093	            view.setResponseMaxChunkSizeBytes(getResponseMaxChunkSizeBytes());
1094	        }
1095	
1096	        return Mono.just(view);
1097	
1098	    }
