package org.thymeleaf.spring6.view;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

import jakarta.servlet.ServletException;

import org.junit.jupiter.api.Test;
import org.springframework.web.servlet.support.RequestContext;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.mock;

class AbstractThymeleafViewTest {

    private static final class TestView extends AbstractThymeleafView {

        private TestView() {
            super();
        }

        private TestView(final String templateName) {
            super(templateName);
        }

        private boolean contentTypeSetForTest() {
            return isContentTypeSet();
        }

        private boolean forceContentTypeSetForTest() {
            return isForceContentTypeSet();
        }

        private boolean partialOutputSetForTest() {
            return isProducePartialOutputWhileProcessingSet();
        }

        private Locale localeForTest() {
            return getLocale();
        }

        private void localeForTest(final Locale locale) {
            setLocale(locale);
        }

        private static void addRequestContextForTest(
                final Map<String, Object> model, final String variableName, final RequestContext requestContext)
                throws ServletException {
            addRequestContextAsVariable(model, variableName, requestContext);
        }
    }

    @Test
    void exposesDocumentedDefaults() {
        final TestView view = new TestView();

        assertEquals("text/html;charset=ISO-8859-1", AbstractThymeleafView.DEFAULT_CONTENT_TYPE);
        assertTrue(AbstractThymeleafView.DEFAULT_PRODUCE_PARTIAL_OUTPUT_WHILE_PROCESSING);
        assertEquals(AbstractThymeleafView.DEFAULT_CONTENT_TYPE, view.getContentType());
        assertNull(view.getCharacterEncoding());
        assertFalse(view.getForceContentType());
        assertTrue(view.getProducePartialOutputWhileProcessing());
        assertNull(view.getTemplateName());
        assertNull(view.getBeanName());
        assertTrue(view.getStaticVariables().isEmpty());

        assertFalse(view.contentTypeSetForTest());
        assertFalse(view.forceContentTypeSetForTest());
        assertFalse(view.partialOutputSetForTest());
    }

    @Test
    void settersRoundTripValuesAndTrackExplicitConfiguration() {
        final TestView view = new TestView("initial");

        view.setContentType(null);
        view.setCharacterEncoding("UTF-8");
        view.setForceContentType(true);
        view.setProducePartialOutputWhileProcessing(false);
        view.setBeanName("myView");
        view.setTemplateName("next");
        view.localeForTest(Locale.CANADA_FRENCH);

        assertNull(view.getContentType());
        assertTrue(view.contentTypeSetForTest());
        assertEquals("UTF-8", view.getCharacterEncoding());
        assertTrue(view.getForceContentType());
        assertTrue(view.forceContentTypeSetForTest());
        assertFalse(view.getProducePartialOutputWhileProcessing());
        assertTrue(view.partialOutputSetForTest());
        assertEquals("myView", view.getBeanName());
        assertEquals("next", view.getTemplateName());
        assertEquals(Locale.CANADA_FRENCH, view.localeForTest());
    }

    @Test
    void staticVariablesAreAddedWithoutReplacingTheVariableMapAndAreExposedReadOnly() {
        final TestView view = new TestView();
        view.addStaticVariable("first", "one");

        final Map<String, Object> initialView = view.getStaticVariables();
        assertThrows(UnsupportedOperationException.class, () -> initialView.put("forbidden", "value"));

        view.addStaticVariable("second", 2);
        assertEquals(Map.of("first", "one", "second", 2), view.getStaticVariables());

        final Map<String, Object> moreVariables = new HashMap<>();
        moreVariables.put("third", 3);
        view.setStaticVariables(moreVariables);
        view.setStaticVariables(null);

        assertEquals(Map.of("first", "one", "second", 2, "third", 3), view.getStaticVariables());
        assertThrows(UnsupportedOperationException.class, () -> view.getStaticVariables().clear());
    }

    @Test
    void templateNameCanBeProvidedAtConstructionTime() {
        assertEquals("home", new TestView("home").getTemplateName());
        assertNull(new TestView().getTemplateName());
    }

    @Test
    void addingRequestContextRejectsNameCollisionAndLeavesModelUntouched() {
        final Map<String, Object> model = new HashMap<>();
        final Object existing = new Object();
        model.put("requestContext", existing);
        final RequestContext requestContext = mock(RequestContext.class);

        final ServletException exception = assertThrows(
                ServletException.class,
                () -> TestView.addRequestContextForTest(model, "requestContext", requestContext));

        assertTrue(exception.getMessage().contains("requestContext"));
        assertSame(existing, model.get("requestContext"));
        assertEquals(1, model.size());
    }

    @Test
    void addingRequestContextStoresTheSuppliedInstance() throws Exception {
        final Map<String, Object> model = new HashMap<>();
        final RequestContext requestContext = mock(RequestContext.class);

        TestView.addRequestContextForTest(model, "requestContext", requestContext);

        assertEquals(1, model.size());
        assertSame(requestContext, model.get("requestContext"));
    }
}
