package org.thymeleaf.spring6.view;

import java.io.PrintWriter;
import java.io.StringWriter;
import java.util.Collection;
import java.util.Collections;
import java.util.Enumeration;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

import jakarta.servlet.ServletContext;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.context.ApplicationContext;
import org.springframework.web.context.WebApplicationContext;
import org.springframework.web.context.support.GenericWebApplicationContext;
import org.springframework.web.servlet.View;
import org.thymeleaf.IEngineConfiguration;
import org.thymeleaf.context.IContext;
import org.thymeleaf.spring6.ISpringTemplateEngine;
import org.thymeleaf.spring6.expression.ThymeleafEvaluationContext;
import org.thymeleaf.spring6.naming.SpringContextVariableNames;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.ArgumentMatchers.isNull;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

class ThymeleafViewTest {

    private ServletContext servletContext;
    private HttpServletRequest request;
    private HttpServletResponse response;
    private StringWriter responseBody;
    private PrintWriter responseWriter;
    private GenericWebApplicationContext applicationContext;
    private ISpringTemplateEngine templateEngine;
    private IEngineConfiguration engineConfiguration;

    @BeforeEach
    void setUp() {
        servletContext = mock(ServletContext.class);
        request = mock(HttpServletRequest.class);
        response = mock(HttpServletResponse.class);
        responseBody = new StringWriter();
        responseWriter = new PrintWriter(responseBody);

        applicationContext = new GenericWebApplicationContext();
        applicationContext.setServletContext(servletContext);
        applicationContext.refresh();

        when(servletContext.getContextPath()).thenReturn("");
        when(servletContext.getAttributeNames()).thenReturn(Collections.emptyEnumeration());
        when(request.getServletContext()).thenReturn(servletContext);
        when(request.getAttribute(WebApplicationContext.ROOT_WEB_APPLICATION_CONTEXT_ATTRIBUTE))
                .thenReturn(applicationContext);
        when(request.getAttributeNames()).thenReturn(Collections.emptyEnumeration());
        when(request.getContextPath()).thenReturn("");
        when(request.getMethod()).thenReturn("GET");
        when(request.getScheme()).thenReturn("http");
        when(request.getServerName()).thenReturn("localhost");
        when(request.getServerPort()).thenReturn(80);
        when(request.getRequestURI()).thenReturn("/application/home");
        when(request.getHeaderNames()).thenReturn(Collections.emptyEnumeration());
        when(request.getHeaders(anyString())).thenReturn(Collections.emptyEnumeration());
        when(request.getParameterMap()).thenReturn(Collections.emptyMap());
        when(response.getWriter()).thenReturn(responseWriter);
        when(response.getLocale()).thenReturn(Locale.US);

        templateEngine = mock(ISpringTemplateEngine.class);
        engineConfiguration = mock(IEngineConfiguration.class);
        when(templateEngine.getConfiguration()).thenReturn(engineConfiguration);
        when(templateEngine.getAllowedClassOverridesForViews()).thenReturn(Collections.emptyList());
        doAnswer(invocation -> {
            invocation.<java.io.Writer>getArgument(3).write("processed-output");
            return null;
        }).when(templateEngine).process(anyString(), any(), any(IContext.class), any(java.io.Writer.class));
    }

    private ThymeleafView configuredView() {
        final ThymeleafView view = new ThymeleafView("home");
        view.setApplicationContext(applicationContext);
        view.setTemplateEngine(templateEngine);
        view.setLocale(Locale.US);
        return view;
    }

    @Test
    void constructorAndMarkupSelectorNormalizeTheirInput() {
        assertEquals("home", new ThymeleafView("home").getTemplateName());
        assertNull(new ThymeleafView().getTemplateName());

        final ThymeleafView view = new ThymeleafView();
        assertNull(view.getMarkupSelector());
        view.setMarkupSelector("  main content  ");
        assertEquals("main content", view.getMarkupSelector());
        view.setMarkupSelector("   ");
        assertNull(view.getMarkupSelector());
        view.setMarkupSelector(null);
        assertNull(view.getMarkupSelector());
    }

    @Test
    void renderRejectsMissingTemplateNameLocaleAndTemplateEngine() {
        final Map<String, Object> model = Collections.emptyMap();

        final ThymeleafView noTemplate = new ThymeleafView();
        noTemplate.setApplicationContext(applicationContext);
        noTemplate.setTemplateEngine(templateEngine);
        noTemplate.setLocale(Locale.US);
        final IllegalArgumentException templateError = assertThrows(
                IllegalArgumentException.class, () -> noTemplate.render(model, request, response));
        assertEquals("Property 'templateName' is required", templateError.getMessage());

        final ThymeleafView noLocale = new ThymeleafView("home");
        noLocale.setApplicationContext(applicationContext);
        noLocale.setTemplateEngine(templateEngine);
        final IllegalArgumentException localeError = assertThrows(
                IllegalArgumentException.class, () -> noLocale.render(model, request, response));
        assertEquals("Property 'locale' is required", localeError.getMessage());

        final ThymeleafView noEngine = new ThymeleafView("home");
        noEngine.setApplicationContext(applicationContext);
        noEngine.setLocale(Locale.US);
        final IllegalArgumentException engineError = assertThrows(
                IllegalArgumentException.class, () -> noEngine.render(model, request, response));
        assertEquals("Property 'templateEngine' is required", engineError.getMessage());
    }

    @Test
    void renderMergesModelAndPublishesThymeleafContextVariables() throws Exception {
        final ThymeleafView view = configuredView();
        view.setApplicationContext(applicationContext);
        view.addStaticVariable("staticOnly", "static-value");
        view.addStaticVariable("overridden", "from-static");
        when(request.getAttribute(View.PATH_VARIABLES)).thenReturn(Map.of("pathOnly", 7L, "overridden", "from-path"));

        final Map<String, Object> model = new HashMap<>();
        model.put("modelOnly", "model-value");
        model.put("overridden", "from-model");

        view.render(model, request, response);

        final org.mockito.ArgumentCaptor<IContext> contextCaptor =
                org.mockito.ArgumentCaptor.forClass(IContext.class);
        verify(templateEngine).process(eq("home"), isNull(), contextCaptor.capture(), any(java.io.Writer.class));

        final IContext context = contextCaptor.getValue();
        assertEquals("static-value", context.getVariable("staticOnly"));
        assertEquals(7L, context.getVariable("pathOnly"));
        assertEquals("model-value", context.getVariable("modelOnly"));
        assertEquals("from-model", context.getVariable("overridden"));
        assertNotNull(context.getVariable(SpringContextVariableNames.SPRING_REQUEST_CONTEXT));
        assertNotNull(context.getVariable(SpringContextVariableNames.THYMELEAF_REQUEST_CONTEXT));
        assertNotNull(context.getVariable(org.springframework.web.servlet.view.AbstractTemplateView.SPRING_MACRO_REQUEST_CONTEXT_ATTRIBUTE));
        assertTrue(context.getVariable(ThymeleafEvaluationContext.THYMELEAF_EVALUATION_CONTEXT_CONTEXT_VARIABLE_NAME)
                instanceof ThymeleafEvaluationContext);
        assertEquals("processed-output", responseBody.toString());
    }

    @Test
    void renderUsesConfiguredMarkupSelector() throws Exception {
        final ThymeleafView view = configuredView();
        view.setMarkupSelector(" main ");

        view.render(Collections.emptyMap(), request, response);

        final org.mockito.ArgumentCaptor<Set<String>> selectorCaptor =
                org.mockito.ArgumentCaptor.forClass(Set.class);
        verify(templateEngine).process(eq("home"), selectorCaptor.capture(), any(IContext.class), any(java.io.Writer.class));
        assertEquals(Set.of("main"), selectorCaptor.getValue());
    }

