        assertNull(resolver.getExcludedViewNames());
        assertNull(resolver.getFullModeViewNames());
        assertNull(resolver.getChunkedModeViewNames());
        assertNotNull(resolver.getRedirectViewProvider());
        assertSame(applicationContext, resolver.getApplicationContext());
        assertSame(templateEngine, resolver.getTemplateEngine());
        assertTrue(resolver.getStaticVariables().isEmpty());
        assertFalse(resolver.getSupportedMediaTypes().isEmpty());
        assertTrue(resolver.getSupportedMediaTypes().contains(MediaType.TEXT_HTML));

