        resolver.setAlwaysProcessRedirectAndForward(false);
        resolver.setResponseMaxChunkSizeBytes(512);
        resolver.setViewNames(new String[]{"public/*"});
        resolver.setExcludedViewNames(new String[]{"public/private*"});
        resolver.setFullModeViewNames(new String[]{"large/*"});
        resolver.setChunkedModeViewNames(new String[]{"streamed/*"});
        resolver.setDefaultCharset(StandardCharsets.UTF_8);
        resolver.addStaticVariable("one", 1);
        resolver.setStaticVariables(Map.of("two", 2));

        assertEquals(11, resolver.getOrder());
        assertFalse(resolver.getAlwaysProcessRedirectAndForward());
        assertEquals(512, resolver.getResponseMaxChunkSizeBytes());
        assertArrayEquals(new String[]{"public/*"}, resolver.getViewNames());
        assertArrayEquals(new String[]{"public/private*"}, resolver.getExcludedViewNames());
        assertArrayEquals(new String[]{"large/*"}, resolver.getFullModeViewNames());
        assertArrayEquals(new String[]{"streamed/*"}, resolver.getChunkedModeViewNames());
        assertEquals(StandardCharsets.UTF_8, resolver.getDefaultCharset());
        assertEquals(Map.of("one", 1, "two", 2), resolver.getStaticVariables());
        assertThrows(UnsupportedOperationException.class, () -> resolver.getStaticVariables().clear());
    }

