    void chunkSizeIsPropagatedOnlyToViewsSelectedForChunkedExecution() {
        resolver.setResponseMaxChunkSizeBytes(256);
        resolver.setChunkedModeViewNames(new String[]{"streamed/*"});

        final TestReactiveView streamed = assertInstanceOf(
