        assertEquals(256, streamed.getResponseMaxChunkSizeBytes());
        assertEquals(ThymeleafReactiveView.DEFAULT_RESPONSE_CHUNK_SIZE_BYTES,
                regular.getResponseMaxChunkSizeBytes());
    }

