 * ----------------------------------------------------------------------------------------------------------
 */

final String templateName;
final Set<String> markupSelectors;
if (!viewTemplateName.contains("::")) {
    // No fragment specified at the template name

    templateName = viewTemplateName;
    markupSelectors = null;

} else {
