    }
    if (getLocale() == null) {
        return Mono.error(new IllegalArgumentException("Property 'locale' is required"));
    }
    if (viewTemplateEngine == null) {
        return Mono.error(new IllegalArgumentException("Property 'thymeleafTemplateEngine' is required"));
    }

