import org.springframework.web.servlet.support.RequestContext;
import org.thymeleaf.spring5.ISpringTemplateEngine;

class AbstractThymeleafViewTest {


    @Test
    void defaultValuesMatchDocumentedContract() {

        final TestView view = new TestView();

        assertEquals("text/html;charset=ISO-8859-1", AbstractThymeleafView.DEFAULT_CONTENT_TYPE);
        assertEquals(AbstractThymeleafView.DEFAULT_CONTENT_TYPE, view.getContentType());
        assertFalse(view.isContentTypeSet());
        assertFalse(view.getForceContentType());
        assertFalse(view.isForceContentTypeSet());
        assertNull(view.getCharacterEncoding());
        assertTrue(view.getProducePartialOutputWhileProcessing());
        assertTrue(AbstractThymeleafView.DEFAULT_PRODUCE_PARTIAL_OUTPUT_WHILE_PROCESSING);
        assertFalse(view.isProducePartialOutputWhileProcessingSet());
        assertNull(view.getBeanName());
        assertNull(view.getTemplateName());
        assertNull(view.exposedLocale());
        assertNull(view.exposedTemplateEngine());
        assertTrue(view.getStaticVariables().isEmpty());

    }


    @Test
    void templateNameCanBeProvidedAtConstructionOrBySetter() {

        final TestView constructed = new TestView("initial");
        assertEquals("initial", constructed.getTemplateName());
        constructed.setTemplateName("changed");
        assertEquals("changed", constructed.getTemplateName());

        final TestView empty = new TestView();
        empty.setTemplateName("later");
        assertEquals("later", empty.getTemplateName());
        empty.setTemplateName(null);
        assertNull(empty.getTemplateName());

    }


    @Test
    void scalarPropertiesAreStoredAndTheirExplicitlySetFlagsAreUpdated() {

        final TestView view = new TestView();

        view.setContentType("application/json");
        assertEquals("application/json", view.getContentType());
        assertTrue(view.isContentTypeSet());

        view.setForceContentType(true);
        assertTrue(view.getForceContentType());
        assertTrue(view.isForceContentTypeSet());

        view.setProducePartialOutputWhileProcessing(false);
        assertFalse(view.getProducePartialOutputWhileProcessing());
        assertTrue(view.isProducePartialOutputWhileProcessingSet());

        view.setCharacterEncoding("UTF-8");
        assertEquals("UTF-8", view.getCharacterEncoding());

        view.setBeanName("myView");
        assertEquals("myView", view.getBeanName());

        final Locale locale = Locale.CANADA_FRENCH;
        view.exposedLocale(locale);
        assertSame(locale, view.exposedLocale());

        final ISpringTemplateEngine engine = mock(ISpringTemplateEngine.class);
        view.exposedTemplateEngine(engine);
        assertSame(engine, view.exposedTemplateEngine());

    }


    @Test
    void contentTypeCanBeExplicitlySetToNull() {

        final TestView view = new TestView();

        view.setContentType(null);

        assertNull(view.getContentType());
        assertTrue(view.isContentTypeSet());

    }


    @Test
    void staticVariablesAreAddedAndExposedAsUnmodifiableMap() {

        final TestView view = new TestView();

        view.addStaticVariable("first", "value1");
        view.addStaticVariable("second", 2);

        final Map<String, Object> variables = view.getStaticVariables();
        assertEquals(2, variables.size());
        assertEquals("value1", variables.get("first"));
        assertEquals(2, variables.get("second"));
        assertThrows(UnsupportedOperationException.class, () -> variables.put("third", 3));

    }


    @Test
    void setStaticVariablesMergesIntoAlreadyExistingVariables() {

        final TestView view = new TestView();
        view.addStaticVariable("existing", "kept");

        final Map<String, Object> additional = new HashMap<String, Object>();
        additional.put("newValue", "added");
        view.setStaticVariables(additional);

        assertEquals("kept", view.getStaticVariables().get("existing"));
        assertEquals("added", view.getStaticVariables().get("newValue"));

        view.setStaticVariables(null);
        assertEquals(2, view.getStaticVariables().size());

    }


    @Test
    void addRequestContextAsVariablePutsTheContextWhenNameIsFree() throws Exception {

        final TestView view = new TestView();
        final Map<String, Object> model = new HashMap<String, Object>();
        final RequestContext requestContext = mock(RequestContext.class);

        view.addRequestContext(model, "ctx", requestContext);

        assertEquals(1, model.size());
        assertSame(requestContext, model.get("ctx"));

    }


    @Test
    void addRequestContextAsVariableRejectsAlreadyUsedNames() {

        final TestView view = new TestView();
        final Map<String, Object> model = new HashMap<String, Object>();
        model.put("ctx", "already-here");

        final ServletException exception = assertThrows(
                ServletException.class,
                () -> view.addRequestContext(model, "ctx", mock(RequestContext.class)));

        assertTrue(exception.getMessage().contains("Cannot expose request context in model attribute 'ctx'"));
        assertEquals("already-here", model.get("ctx"));

    }


    @Test
    void emptyStaticVariablesAreNotSharedWithCallers() {

        final TestView view = new TestView();

        final Map<String, Object> variables = view.getStaticVariables();
        assertThrows(UnsupportedOperationException.class, () -> variables.put("x", "y"));
        assertTrue(view.getStaticVariables().isEmpty());

    }


    private static final class TestView extends AbstractThymeleafView {

        private TestView() {
            super();
        }

        private TestView(final String templateName) {
            super(templateName);
        }

        private Locale exposedLocale() {
            return getLocale();
        }

        private void exposedLocale(final Locale locale) {
            setLocale(locale);
        }

        private ISpringTemplateEngine exposedTemplateEngine() {
            return getTemplateEngine();
        }

        private void exposedTemplateEngine(final ISpringTemplateEngine templateEngine) {
            setTemplateEngine(templateEngine);
        }

        private void addRequestContext(
                final Map<String, Object> model, final String name, final RequestContext requestContext)
                throws ServletException {
            addRequestContextAsVariable(model, name, requestContext);
        }

    }

}
