class ThymeleafViewResolverTest {


    @Test
    void defaultsAndSimpleProperties() {

        final ThymeleafViewResolver resolver = new ThymeleafViewResolver();

        assertSame(ThymeleafView.class, resolver.getViewClass());
        assertNull(resolver.getTemplateEngine());
        assertNull(resolver.getContentType());
        assertEquals("redirect:", ThymeleafViewResolver.REDIRECT_URL_PREFIX);
        assertEquals("forward:", ThymeleafViewResolver.FORWARD_URL_PREFIX);
        assertTrue(resolver.isRedirectContextRelative());
        assertTrue(resolver.isRedirectHttp10Compatible());
        assertNull(resolver.getRedirectViewProvider());
        assertTrue(resolver.getAlwaysProcessRedirectAndForward());
        assertTrue(resolver.getProducePartialOutputWhileProcessing());
        assertFalse(resolver.getForceContentType());
        assertNull(resolver.getCharacterEncoding());
        assertEquals(Integer.MAX_VALUE, resolver.getOrder());
        assertNull(resolver.getViewNames());
        assertNull(resolver.getExcludedViewNames());
        assertTrue(resolver.getStaticVariables().isEmpty());

        final ISpringTemplateEngine engine = mock(ISpringTemplateEngine.class);
        resolver.setTemplateEngine(engine);
        assertSame(engine, resolver.getTemplateEngine());

        resolver.setContentType("text/plain");
        assertEquals("text/plain", resolver.getContentType());

        resolver.setCharacterEncoding("UTF-8");
        assertEquals("UTF-8", resolver.getCharacterEncoding());

        resolver.setForceContentType(true);
        assertTrue(resolver.getForceContentType());

        resolver.setRedirectContextRelative(false);
        assertFalse(resolver.isRedirectContextRelative());

        resolver.setRedirectHttp10Compatible(false);
        assertFalse(resolver.isRedirectHttp10Compatible());

        resolver.setAlwaysProcessRedirectAndForward(false);
        assertFalse(resolver.getAlwaysProcessRedirectAndForward());

        resolver.setProducePartialOutputWhileProcessing(false);
        assertFalse(resolver.getProducePartialOutputWhileProcessing());

        resolver.setOrder(12);
        assertEquals(12, resolver.getOrder());

    }


    @Test
    void viewClassMustBeAnAbstractThymeleafViewSubclass() {

        final ThymeleafViewResolver resolver = new ThymeleafViewResolver();

        assertThrows(IllegalArgumentException.class, () -> resolver.setViewClass(null));

        @SuppressWarnings({"rawtypes", "unchecked"})
        final Class<? extends AbstractThymeleafView> incompatibleClass = (Class) String.class;
        final IllegalArgumentException exception = assertThrows(
                IllegalArgumentException.class, () -> resolver.setViewClass(incompatibleClass));
        assertTrue(exception.getMessage().contains(String.class.getName()));
        assertTrue(exception.getMessage().contains(AbstractThymeleafView.class.getName()));

        resolver.setViewClass(CustomThymeleafView.class);
        assertSame(CustomThymeleafView.class, resolver.getViewClass());

    }


    @Test
    void staticVariablesAreMergedAndExposedUnmodifiable() {

        final ThymeleafViewResolver resolver = new ThymeleafViewResolver();

        resolver.addStaticVariable("one", 1);
        final Map<String, Object> more = new LinkedHashMap<String, Object>();
        more.put("two", 2);
        resolver.setStaticVariables(more);

        assertEquals(1, resolver.getStaticVariables().get("one"));
        assertEquals(2, resolver.getStaticVariables().get("two"));
        assertThrows(UnsupportedOperationException.class, () -> resolver.getStaticVariables().put("three", 3));

        resolver.setStaticVariables(null);
        assertEquals(2, resolver.getStaticVariables().size());

    }


    @Test
    void viewNamePropertiesAndCanHandleUseSimplePatterns() {

        final ThymeleafViewResolver resolver = new ThymeleafViewResolver();

        assertTrue(resolver.canHandle("anything", Locale.US));

        final String[] included = new String[]{"admin/*", "index"};
        resolver.setViewNames(included);
        assertArrayEquals(included, resolver.getViewNames());
        assertTrue(resolver.canHandle("admin/home", Locale.US));
        assertTrue(resolver.canHandle("index", Locale.US));
        assertFalse(resolver.canHandle("other", Locale.US));

        final String[] excluded = new String[]{"admin/private*"};
        resolver.setExcludedViewNames(excluded);
        assertArrayEquals(excluded, resolver.getExcludedViewNames());
        assertFalse(resolver.canHandle("admin/privatePage", Locale.US));
        assertTrue(resolver.canHandle("admin/publicPage", Locale.US));

    }


    @Test
    void createViewBuildsRedirectViewUsingTheConfiguredOptions() throws Exception {

        final ThymeleafViewResolver resolver = new ThymeleafViewResolver();
        resolver.setApplicationContext(newContext());
        resolver.setRedirectContextRelative(false);
        resolver.setRedirectHttp10Compatible(false);

        final View view = resolver.createView("redirect:/target", Locale.US);

        assertTrue(view instanceof RedirectView);
        assertEquals("/target", ((RedirectView) view).getUrl());

    }


    @Test
    void redirectViewProviderReceivesUrlWithoutPrefixAndControlsTheView() throws Exception {

        final ThymeleafViewResolver resolver = new ThymeleafViewResolver();
        resolver.setApplicationContext(newContext());

        final AtomicReference<String> providedUrl = new AtomicReference<String>();
        final RedirectView customView = new RedirectView("/custom");
        final Function<String, RedirectView> provider = url -> {
            providedUrl.set(url);
            return customView;
        };
        resolver.setRedirectViewProvider(provider);

        assertSame(provider, resolver.getRedirectViewProvider());

        final View view = resolver.createView("redirect:/target", Locale.US);

        assertSame(customView, view);
        assertEquals("/target", providedUrl.get());

    }


    @Test
    void redirectViewProviderCannotBeNull() {

        final ThymeleafViewResolver resolver = new ThymeleafViewResolver();

        assertThrows(IllegalArgumentException.class, () -> resolver.setRedirectViewProvider(null));

    }


    @Test
    void forwardViewNamesProduceInternalResourceViews() throws Exception {

        final ThymeleafViewResolver resolver = new ThymeleafViewResolver();
        resolver.setApplicationContext(newContext());

        final View view = resolver.createView("forward:/WEB-INF/templates/page.jsp", Locale.US);

        assertTrue(view instanceof InternalResourceView);
        assertEquals("/WEB-INF/templates/page.jsp", ((InternalResourceView) view).getUrl());

    }


    @Test
    void redirectsAndForwardsCanBeFilteredByViewNames() throws Exception {

        final ThymeleafViewResolver resolver = new ThymeleafViewResolver();
        resolver.setApplicationContext(newContext());
        resolver.setAlwaysProcessRedirectAndForward(false);
        resolver.setViewNames(new String[]{"home"});

        assertNull(resolver.createView("redirect:/target", Locale.US));
        assertNull(resolver.createView("forward:/target", Locale.US));

        resolver.setAlwaysProcessRedirectAndForward(true);
        assertNotNull(resolver.createView("redirect:/target", Locale.US));
        assertNotNull(resolver.createView("forward:/target", Locale.US));

    }


    @Test
    void nonMatchingViewNamesAreNotHandled() throws Exception {

        final ThymeleafViewResolver resolver = new ThymeleafViewResolver();
        resolver.setApplicationContext(newContext());
        resolver.setViewNames(new String[]{"admin/*"});

        assertNull(resolver.createView("home", Locale.US));

    }


    @Test
    void createViewConfiguresANewViewWithResolverWideValues() throws Exception {

        final ThymeleafViewResolver resolver = new ThymeleafViewResolver();
        resolver.setApplicationContext(newContext());
        final ISpringTemplateEngine engine = mock(ISpringTemplateEngine.class);
        resolver.setTemplateEngine(engine);
        resolver.setContentType("text/plain");
        resolver.setCharacterEncoding("UTF-8");
        resolver.setForceContentType(true);
        resolver.setProducePartialOutputWhileProcessing(false);
        resolver.addStaticVariable("staticVar", "staticValue");

        final View view = resolver.createView("home", Locale.GERMANY);

        assertTrue(view instanceof ThymeleafView);
        final ThymeleafView thymeleafView = (ThymeleafView) view;
        assertEquals("home", thymeleafView.getTemplateName());
        assertEquals("home", thymeleafView.getBeanName());
        assertSame(engine, thymeleafView.getTemplateEngine());
        assertEquals(Locale.GERMANY, thymeleafView.getLocale());
        assertEquals("text/plain", thymeleafView.getContentType());
        assertEquals("UTF-8", thymeleafView.getCharacterEncoding());
        assertTrue(thymeleafView.getForceContentType());
        assertFalse(thymeleafView.getProducePartialOutputWhileProcessing());
        assertEquals("staticValue", thymeleafView.getStaticVariables().get("staticVar"));

    }


    @Test
    void createViewUsesTheConfiguredViewClass() throws Exception {

        final ThymeleafViewResolver resolver = new ThymeleafViewResolver();
        resolver.setApplicationContext(newContext());
        resolver.setViewClass(CustomThymeleafView.class);

        final View view = resolver.createView("home", Locale.US);

        assertTrue(view instanceof CustomThymeleafView);
        assertEquals("home", ((CustomThymeleafView) view).getTemplateName());

    }


    @Test
    void prototypeViewBeansKeepTheirOwnConfigurationValues() throws Exception {

        final GenericApplicationContext context = new GenericApplicationContext();
        final BeanDefinitionBuilder definition = BeanDefinitionBuilder
                .genericBeanDefinition(ThymeleafView.class)
                .setScope(ConfigurableBeanFactory.SCOPE_PROTOTYPE)
                .addPropertyValue("templateName", "fromBean")
                .addPropertyValue("contentType", "application/json")
                .addPropertyValue("characterEncoding", "ISO-8859-1")
                .addPropertyValue("forceContentType", false)
                .addPropertyValue("producePartialOutputWhileProcessing", true);
        context.registerBeanDefinition("custom", definition.getBeanDefinition());
        context.refresh();

        final ThymeleafViewResolver resolver = new ThymeleafViewResolver();
        resolver.setApplicationContext(context);
        resolver.setCache(false);
        final ISpringTemplateEngine engine = mock(ISpringTemplateEngine.class);
        resolver.setTemplateEngine(engine);
        resolver.setContentType("text/plain");
        resolver.setCharacterEncoding("UTF-8");
        resolver.setForceContentType(true);
        resolver.setProducePartialOutputWhileProcessing(false);

        final View first = resolver.createView("custom", Locale.US);
        final View second = resolver.createView("custom", Locale.US);

        assertTrue(first instanceof ThymeleafView);
        assertNotSame(first, second);
        final ThymeleafView view = (ThymeleafView) first;
        assertEquals("fromBean", view.getTemplateName());
        assertEquals("application/json", view.getContentType());
        assertEquals("ISO-8859-1", view.getCharacterEncoding());
        assertFalse(view.getForceContentType());
        assertTrue(view.getProducePartialOutputWhileProcessing());
        assertSame(engine, view.getTemplateEngine());
        assertEquals(Locale.US, view.getLocale());

    }


    @Test
    void singletonViewBeanDefinitionIsUsedAsAPrototypeForProperties() throws Exception {

        final GenericApplicationContext context = new GenericApplicationContext();
        final BeanDefinition beanDefinition = BeanDefinitionBuilder
                .genericBeanDefinition(ThymeleafView.class)
                .addPropertyValue("templateName", "configuredByBean")
                .addPropertyValue("contentType", "application/xhtml+xml")
                .getBeanDefinition();
        context.registerBeanDefinition("configured", beanDefinition);
        context.refresh();

        final ThymeleafViewResolver resolver = new ThymeleafViewResolver();
        resolver.setApplicationContext(context);
        resolver.setContentType("text/plain");
        resolver.setTemplateEngine(mock(ISpringTemplateEngine.class));

        final View view = resolver.createView("configured", Locale.US);

        assertTrue(view instanceof ThymeleafView);
        assertEquals("configuredByBean", ((ThymeleafView) view).getTemplateName());
        assertEquals("application/xhtml+xml", ((ThymeleafView) view).getContentType());

    }


    @Test
    void resolutionIsCachedByDefaultAndCanBeDisabled() throws Exception {

        final ThymeleafViewResolver cachedResolver = new ThymeleafViewResolver();
        cachedResolver.setApplicationContext(newContext());
        cachedResolver.setTemplateEngine(mock(ISpringTemplateEngine.class));

        final View first = cachedResolver.resolveViewName("home", Locale.US);
        final View second = cachedResolver.resolveViewName("home", Locale.US);
        assertSame(first, second);

        final ThymeleafViewResolver nonCachedResolver = new ThymeleafViewResolver();
        nonCachedResolver.setApplicationContext(newContext());
        nonCachedResolver.setTemplateEngine(mock(ISpringTemplateEngine.class));
        nonCachedResolver.setCache(false);

        final View third = nonCachedResolver.resolveViewName("home", Locale.US);
        final View fourth = nonCachedResolver.resolveViewName("home", Locale.US);
        assertNotSame(third, fourth);

    }


    private static GenericApplicationContext newContext() {
        final GenericApplicationContext context = new GenericApplicationContext();
        context.refresh();
        return context;
    }


    public static class CustomThymeleafView extends ThymeleafView {

        public CustomThymeleafView() {
            super();
        }

    }

}
