        additional.put("two", 2);
        view.setStaticVariables(additional);
        view.setStaticVariables(null);

        assertEquals(1, view.getStaticVariables().get("one"));
        assertEquals(2, view.getStaticVariables().get("two"));
        assertThrows(UnsupportedOperationException.class, () -> view.getStaticVariables().put("three", 3));

    }


