        fixture.exchangeAttributes.put(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE, pathVars);

        final Map<String, Object> model = new LinkedHashMap<String, Object>();
        model.put("modelVar", "modelValue");
        model.put("shared", "fromModel");

        fixture.view.renderFragmentInternal(
                Collections.singleton("fragment"), model, MediaType.TEXT_HTML, fixture.exchange).block();

        final ArgumentCaptor<IContext> contextCaptor = ArgumentCaptor.forClass(IContext.class);
        verify(fixture.engine).processStream(
                eq("home"), eq(Collections.singleton("fragment")), contextCaptor.capture(),
                same(fixture.bufferFactory), eq(MediaType.TEXT_HTML),
                eq(StandardCharsets.UTF_8), eq(Integer.MAX_VALUE));

        final IContext context = contextCaptor.getValue();
        assertEquals("staticValue", context.getVariable("staticVar"));
        assertEquals("pathValue", context.getVariable("pathVar"));
        assertEquals("modelValue", context.getVariable("modelVar"));
        assertEquals("fromModel", context.getVariable("shared"));

        assertInstanceOf(
                org.springframework.web.reactive.result.view.RequestContext.class,
                context.getVariable(SpringContextVariableNames.SPRING_REQUEST_CONTEXT));
        assertInstanceOf(
                SpringWebFluxThymeleafRequestContext.class,
                context.getVariable(SpringContextVariableNames.THYMELEAF_REQUEST_CONTEXT));
        assertInstanceOf(
                ThymeleafEvaluationContext.class,
                context.getVariable(ThymeleafEvaluationContext.THYMELEAF_EVALUATION_CONTEXT_CONTEXT_VARIABLE_NAME));

        verify(fixture.headers).setContentLanguage(Locale.US);
        verify(fixture.response).writeWith(any(Publisher.class));
        verify(fixture.response, never()).writeAndFlushWith(any());

    }


    @Test
    void chunkedExecutionUsesConfiguredChunkSizeAndFlushesEachChunk() {

        final RenderFixture fixture = new RenderFixture();
        fixture.view.setResponseMaxChunkSizeBytes(128);

        fixture.view.renderFragmentInternal(
                null, Collections.<String, Object>emptyMap(), MediaType.TEXT_HTML, fixture.exchange).block();

