        assertEquals("configuredByBean", ((ThymeleafReactiveView) view).getTemplateName());
        assertEquals(77, ((ThymeleafReactiveView) view).getResponseMaxChunkSizeBytes());

    }


    private static GenericApplicationContext newContext() {
        final GenericApplicationContext context = new GenericApplicationContext();
        context.refresh();
        return context;
    }

