                .resolveViewName("chunkView", Locale.US).block();
        final ThymeleafReactiveView otherView = (ThymeleafReactiveView) resolver
                .resolveViewName("otherView", Locale.US).block();

        assertEquals(Integer.valueOf(64), chunkedView.getNullableResponseMaxChunkSize());
        assertNull(otherView.getNullableResponseMaxChunkSize());

    }


    @Test
    void nonMatchingViewNamesReturnEmptyMono() {

        final ThymeleafReactiveViewResolver resolver = new ThymeleafReactiveViewResolver();
        resolver.setApplicationContext(newContext());
        resolver.setTemplateEngine(mock(ISpringWebFluxTemplateEngine.class));
        resolver.setViewNames(new String[]{"admin/*"});

        assertNull(resolver.resolveViewName("home", Locale.US).block());
        assertNotNull(resolver.resolveViewName("admin/home", Locale.US).block());

        resolver.setViewNames(null);
        resolver.setExcludedViewNames(new String[]{"admin/*"});
        assertNull(resolver.resolveViewName("admin/home", Locale.US).block());

    }


    @Test
    void redirectViewIsProducedByTheConfiguredProvider() {

        final ThymeleafReactiveViewResolver resolver = new ThymeleafReactiveViewResolver();
        resolver.setApplicationContext(newContext());

        final AtomicReference<String> providedUrl = new AtomicReference<String>();
        final RedirectView customView = new RedirectView("/custom");
        final Function<String, RedirectView> provider = url -> {
            providedUrl.set(url);
            return customView;
        };
        resolver.setRedirectViewProvider(provider);

        final View view = resolver.resolveViewName("redirect:/target", Locale.US).block();

        assertSame(customView, view);
        assertEquals("/target", providedUrl.get());

    }


    @Test
    void forwardsAreNotSupported() {

        final ThymeleafReactiveViewResolver resolver = new ThymeleafReactiveViewResolver();
        resolver.setApplicationContext(newContext());

        final UnsupportedOperationException exception = assertThrows(
                UnsupportedOperationException.class,
                () -> resolver.resolveViewName("forward:/target", Locale.US).block());

        assertTrue(exception.getMessage().contains("Forwards are not currently supported"));

    }


    @Test
    void redirectsCanBeFilteredByViewNamesWhenConfiguredToDoSo() {

        final ThymeleafReactiveViewResolver resolver = new ThymeleafReactiveViewResolver();
        resolver.setApplicationContext(newContext());
        resolver.setAlwaysProcessRedirectAndForward(false);
        resolver.setViewNames(new String[]{"home"});

        assertNull(resolver.resolveViewName("redirect:/target", Locale.US).block());

        resolver.setAlwaysProcessRedirectAndForward(true);
        assertNotNull(resolver.resolveViewName("redirect:/target", Locale.US).block());

    }


    @Test
    void prototypeViewBeansKeepTheirOwnConfiguration() {

        final GenericApplicationContext context = new GenericApplicationContext();
        final BeanDefinitionBuilder definition = BeanDefinitionBuilder
                .genericBeanDefinition(ThymeleafReactiveView.class)
                .setScope(ConfigurableBeanFactory.SCOPE_PROTOTYPE)
                .addPropertyValue("templateName", "fromBean")
                .addPropertyValue("responseMaxChunkSizeBytes", 999)
                .addPropertyValue("defaultCharset", StandardCharsets.ISO_8859_1)
                .addPropertyValue("supportedMediaTypes", Collections.singletonList(MediaType.APPLICATION_JSON));
        context.registerBeanDefinition("custom", definition.getBeanDefinition());
        context.refresh();

        final ThymeleafReactiveViewResolver resolver = new ThymeleafReactiveViewResolver();
        resolver.setApplicationContext(context);
        final ISpringWebFluxTemplateEngine engine = mock(ISpringWebFluxTemplateEngine.class);
        resolver.setTemplateEngine(engine);
        resolver.setDefaultCharset(StandardCharsets.UTF_8);
        resolver.setResponseMaxChunkSizeBytes(128);

        final View first = resolver.resolveViewName("custom", Locale.US).block();
        final View second = resolver.resolveViewName("custom", Locale.US).block();

        assertTrue(first instanceof ThymeleafReactiveView);
        assertNotSame(first, second);
        final ThymeleafReactiveView view = (ThymeleafReactiveView) first;
        assertEquals("fromBean", view.getTemplateName());
        assertEquals(999, view.getResponseMaxChunkSizeBytes());
        assertEquals(StandardCharsets.ISO_8859_1, view.getDefaultCharset());
        assertEquals(Collections.singletonList(MediaType.APPLICATION_JSON), view.getSupportedMediaTypes());
        assertSame(engine, view.getTemplateEngine());
        assertEquals(Locale.US, view.getLocale());

    }


    @Test
    void singletonViewBeanDefinitionIsUsedAsAPrototypeForProperties() {

        final GenericApplicationContext context = new GenericApplicationContext();
        final BeanDefinition beanDefinition = BeanDefinitionBuilder
                .genericBeanDefinition(ThymeleafReactiveView.class)
                .addPropertyValue("templateName", "configuredByBean")
                .addPropertyValue("responseMaxChunkSizeBytes", 77)
                .getBeanDefinition();
        context.registerBeanDefinition("configured", beanDefinition);
        context.refresh();

        final ThymeleafReactiveViewResolver resolver = new ThymeleafReactiveViewResolver();
        resolver.setApplicationContext(context);
        resolver.setTemplateEngine(mock(ISpringWebFluxTemplateEngine.class));

        final View view = resolver.resolveViewName("configured", Locale.US).block();

        assertTrue(view instanceof ThymeleafReactiveView);
        assertEquals("configuredByBean", ((ThymeleafReactiveView) view).getTemplateName());
        assertEquals(77, ((ThymeleafReactiveView) view).getResponseMaxChunkSizeBytes());

    }


    private static GenericApplicationContext newContext() {
        final GenericApplicationContext context = new GenericApplicationContext();
        context.refresh();
        return context;
    }

