    @Test
    void fragmentSpecificationInTemplateNameConflictsWithViewMarkupSelector() {

        final RenderFixture fixture = new RenderFixture();
        fixture.useStandardExpressionParser();
        fixture.view.setTemplateName("template :: content");
        fixture.view.setMarkupSelector("other");

        final IllegalArgumentException exception = assertThrows(
                IllegalArgumentException.class,
                () -> fixture.view.renderInternal(
                        Collections.<String, Object>emptyMap(), MediaType.TEXT_HTML, fixture.exchange).block());

        assertTrue(exception.getMessage().contains("Only one fragment selection is allowed"));

    }


    @Test
    void renderAddsReactiveModelAdditionsToTheViewModel() {

        final RecordingReactiveView view = new RecordingReactiveView();
        final ISpringWebFluxTemplateEngine engine = mock(ISpringWebFluxTemplateEngine.class);
        final IEngineConfiguration configuration = mock(IEngineConfiguration.class);
        when(engine.getConfiguration()).thenReturn(configuration);

        final Map<String, Object> executionAttributes = new HashMap<String, Object>();
        executionAttributes.put("ThymeleafReactiveModelAdditions:fromPublisher", Mono.just("published"));
        executionAttributes.put(
                "ThymeleafReactiveModelAdditions:fromSupplier",
                (Supplier<Publisher<?>>) () -> Mono.just("supplied"));
        executionAttributes.put(
                "ThymeleafReactiveModelAdditions:fromFunction",
                (Function<ServerWebExchange, Publisher<?>>) exchange -> Mono.just("functioned"));
        executionAttributes.put("unrelatedAttribute", "ignored");
        when(configuration.getExecutionAttributes()).thenReturn(executionAttributes);

        view.setTemplateName("home");
        view.setLocale(Locale.US);
        view.setTemplateEngine(engine);

        final ServerWebExchange exchange = mock(ServerWebExchange.class);
        final ServerHttpResponse response = mock(ServerHttpResponse.class);
        when(exchange.getResponse()).thenReturn(response);
        when(response.getHeaders()).thenReturn(mock(HttpHeaders.class));
        when(exchange.getAttributes()).thenReturn(new HashMap<String, Object>());

        view.render(Collections.<String, Object>singletonMap("original", "value"), MediaType.TEXT_HTML, exchange)
                .block();

        assertEquals("value", view.capturedModel.get("original"));
        assertEquals("published", view.capturedModel.get("fromPublisher"));
        assertEquals("supplied", view.capturedModel.get("fromSupplier"));
        assertEquals("functioned", view.capturedModel.get("fromFunction"));
        assertFalse(view.capturedModel.containsKey("unrelatedAttribute"));

    }


