        private final Map<String, Object> exchangeAttributes;
        private final ReactiveTestView view;

        private RenderFixture() {

            this.engine = mock(ISpringWebFluxTemplateEngine.class);
            this.configuration = mock(IEngineConfiguration.class);
            when(this.engine.getConfiguration()).thenReturn(this.configuration);
            when(this.configuration.getExecutionAttributes()).thenReturn(new HashMap<String, Object>());
            this.bufferFactory = mock(DataBufferFactory.class);
            final DataBuffer dataBuffer = mock(DataBuffer.class);
            when(this.engine.processStream(
