                    .thenReturn(Flux.just(dataBuffer));

            this.applicationContext = mock(ApplicationContext.class);
            when(this.applicationContext.containsBean(anyString())).thenReturn(false);
            when(this.applicationContext.getBean(ReactiveAdapterRegistry.class))
            this.exchangeAttributes = new HashMap<String, Object>();
            final LocaleContext localeContext = mock(LocaleContext.class);
            when(localeContext.getLocale()).thenReturn(Locale.US);
            this.exchange = mock(ServerWebExchange.class);
            when(this.exchange.getResponse()).thenReturn(this.response);
            when(this.exchange.getAttributes()).thenReturn(this.exchangeAttributes);
            when(this.exchange.getRequest()).thenReturn(mock(ServerHttpRequest.class));
            when(this.exchange.getLocaleContext()).thenReturn(localeContext);

            this.view = new ReactiveTestView();
            this.view.setApplicationContext(this.applicationContext);
            this.view.setTemplateName("home");
            this.view.setLocale(Locale.US);
            this.view.setTemplateEngine(this.engine);

        }

        private void useStandardExpressionParser() {
            final Map<String, Object> executionAttributes = new HashMap<String, Object>();
            executionAttributes.put(
                    StandardExpressions.STANDARD_EXPRESSION_PARSER_ATTRIBUTE_NAME,
                    new StandardExpressionParser());
            executionAttributes.put(
                    StandardExpressions.STANDARD_VARIABLE_EXPRESSION_EVALUATOR_ATTRIBUTE_NAME,
                    SPELVariableExpressionEvaluator.INSTANCE);
            when(this.configuration.getExecutionAttributes()).thenReturn(executionAttributes);
        }

    }


    private static class ReactiveTestView extends ThymeleafReactiveView {

        private ReactiveTestView() {
            super();
        }

    }


    private static final class RecordingReactiveView extends ThymeleafReactiveView {

        private Map<String, Object> capturedModel;

        private RecordingReactiveView() {
            super();
        }

        @Override
        protected Mono<Void> renderInternal(
                final Map<String, Object> renderAttributes, final MediaType contentType,
                final ServerWebExchange exchange) {
            this.capturedModel = renderAttributes;
            return Mono.empty();
        }

    }

